def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    indexed = [ranks[value] for value in a]
    size = len(ranks)
    tree = [0] * (size + 1)
    result = []

    for i, rank in enumerate(indexed):
        not_taller = 0
        pos = rank
        while pos > 0:
            not_taller += tree[pos]
            pos -= pos & -pos

        result.append(min(i, k) - not_taller)

        pos = rank
        while pos <= size:
            tree[pos] += 1
            pos += pos & -pos

        if i >= k:
            pos = indexed[i - k]
            while pos <= size:
                tree[pos] -= 1
                pos += pos & -pos

    return result
